9	/// ## What it does
10	/// Checks for `return {value}` statements in functions that also contain `yield`
11	/// or `yield from` statements.
12	///
13	/// ## Why is this bad?
14	/// Using `return {value}` in a generator function was syntactically invalid in
15	/// Python 2. In Python 3 `return {value}` _can_ be used in a generator; however,
16	/// the combination of `yield` and `return` can lead to confusing behavior, as
17	/// the `return` statement will cause the generator to raise `StopIteration`
18	/// with the value provided, rather than returning the value to the caller.
19	///
20	/// For example, given:
21	/// ```python
22	/// from collections.abc import Iterable
23	/// from pathlib import Path
24	///
25	///
26	/// def get_file_paths(file_types: Iterable[str] | None = None) -> Iterable[Path]:
27	///     dir_path = Path(".")
28	///     if file_types is None:
29	///         return dir_path.glob("*")
30	///
31	///     for file_type in file_types:
32	///         yield from dir_path.glob(f"*.{file_type}")
33	/// ```
34	///
35	/// Readers might assume that `get_file_paths()` would return an iterable of
36	/// `Path` objects in the directory; in reality, though, `list(get_file_paths())`
37	/// evaluates to `[]`, since the `return` statement causes the generator to raise
38	/// `StopIteration` with the value `dir_path.glob("*")`:
39	///
40	/// ```shell
41	/// >>> list(get_file_paths(file_types=["cfg", "toml"]))
42	/// [PosixPath('setup.cfg'), PosixPath('pyproject.toml')]
43	/// >>> list(get_file_paths())
44	/// []
45	/// ```
46	///
47	/// For intentional uses of `return` in a generator, consider suppressing this
48	/// diagnostic.
49	///
50	/// ## Example
51	/// ```python
52	/// from collections.abc import Iterable
53	/// from pathlib import Path
54	///
55	///
56	/// def get_file_paths(file_types: Iterable[str] | None = None) -> Iterable[Path]:
57	///     dir_path = Path(".")
58	///     if file_types is None:
59	///         return dir_path.glob("*")
60	///
61	///     for file_type in file_types:
62	///         yield from dir_path.glob(f"*.{file_type}")
63	/// ```
64	///
65	/// Use instead:
66	///
67	/// ```python
68	/// from collections.abc import Iterable
69	/// from pathlib import Path
70	///
71	///
72	/// def get_file_paths(file_types: Iterable[str] | None = None) -> Iterable[Path]:
73	///     dir_path = Path(".")
74	///     if file_types is None:
75	///         yield from dir_path.glob("*")
76	///     else:
77	///         for file_type in file_types:
78	///             yield from dir_path.glob(f"*.{file_type}")
79	/// ```
80	#[derive(ViolationMetadata)]
81	#[violation_metadata(preview_since = "v0.4.8")]
82	pub(crate) struct ReturnInGenerator;
83	
84	impl Violation for ReturnInGenerator {
85	    #[derive_message_formats]
86	    fn message(&self) -> String {
87	        "Using `yield` and `return {value}` in a generator function can lead to confusing behavior"
88	            .to_string()
89	    }
90	}
